#include <unordered_map>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;
vector<vector<string>> groupAnagrams(vector<string>&strs) {
    unordered_map<string, vector<string>>m;
    for (auto&s:strs) {
        string k=s;
        sort(k.begin(), k.end());
        m[k].push_back(s);
    }
    vector<vector<string>>res;
    for (auto&p:m)res.push_back(p.second);
    return res;
}

